const D = {"order": ["gemma", "ornith", "gemma-small", "mistral", "qwen-coder"], "subjects": [{"subject": "Shpongle", "slug": "shpongle", "lens": "encyclopedia", "models": {"gemma": {"lede": "Shpongle is an English psychedelic electronic music project formed in 1996. The group consists of Simon Posford and Raja Ram, who are considered progenitors of the psybient genre.", "sections": [{"title": "Musical Style and Composition", "body": "Shpongle's music combines contemporary western synthesizer-based psychedelic music with vocals and traditional music from around the world. Simon Posford is generally responsible for live instrumentation, studio work, and synthesizers, while Raja Ram contributes flute arrangements and broad musical concepts. The project's sound is heavily influenced by psychedelic experiences, utilizing vocal samples related to hallucinations, consciousness expansion, and altered states of awareness, as well as sonic textures that approximate psychedelic states. For example, the track \" la New Way to Say 'Hooray'\" contains a vocal sample of Terence McKenna describing DMT effects."}, {"title": "Discography", "body": "The duo released their first track, \"Vapour Rumours\", in 1996 on the Infinite Excursions compilation. Their debut album, Are You Shpongled?, was released in 1998 and has sold over 30,000 copies; a remastered version of the album was released on June 30, 2017. Studio albums include Tales of the Inexpressible (2001), Nothing Lasts... But Nothing Is Lost (2005), Ineffable Mysteries from Shpongleland (2009), Museum of Consciousness (2013), Codex VI (2017), and Improvisations for Piano & Flute (2024). They have also released several EP albums, including Divine Moments of Truth (2000), Dorset Perception (2004), The God Particle (2010), and Carnival of Peculiarities (2021), as well as remix albums such as Remixed (2003) and Unreleased Remixes (2008)."}, {"title": "Live Performances", "body": "Shpongle's first live performance took place in July 2001 at the Solstice Music Festival in Japan. The project has performed numerous concerts globally, including sold-out shows at The Roundhouse in London and Hammerstein Ballroom in New York City, and headlining dates at festivals such as Ozora in Hungary and Rainbow Serpent in Australia. In 2011, they toured with the Shpongletron, a DJ booth and video-mapped projection surfaces designed by visual artist Zebbler. Their last full public concerts were two consecutive nights at Red Rocks Amphitheatre on May 3 and 4, 2019."}], "facts": [{"label": "Formed", "value": "1996"}, {"label": "Members", "value": "Simon Posford and Raja Ram"}, {"label": "Genre", "value": "Psybient"}, {"label": "First Track", "value": "Vapour Rumours"}, {"label": "Debut Album", "value": "value own Are You Shpongled?"}, {"label": "Last Full Public Concerts", "value": "May 3-4, 2019"}], "secs": null}, "ornith": {"lede": "Shpongle is a psychedelic electronic music project from England formed in 1996 by Simon Posford and Raja Ram. The duo are considered progenitors of the psybient genre, which combines world music with psychedelic trance and ambient styles. Their work frequently incorporates sonic textures approximating psychedelic states and vocal samples related to consciousness expansion.", "sections": [{"heading": "", "body": "Shpongle's musical style combines traditional music from around the world with contemporary western synthesizer-based psychedelic music. Posford is generally responsible for synthesizers, studio work, and live instrumentation, while Raja Ram contributes broad musical concepts and flute arrangements. The name \"Shpongle\" is described by Ram as an umbrella term for feeling positive and euphoric emotions. Their first track, \"Vapour Rumours,\" was released on the Infinite Excursions compilation in 1996."}, {"heading": "", "body": "The group has released seven studio albums: Are You Shpongled? (1998), Tales of the Inexpressible (2001), Nothing Lasts... But Nothing Is Lost (2005), Ineffable Mysteries from Shpongleland (2009), Museum of Consciousness (2013), Codex VI (2017), and Improvisations for Piano & Flute (2024). The debut album sold in excess of 30,000 copies. In addition to studio albums, they have released EPs including Divine Moments of Truth (2000) and several remix albums."}, {"heading": "", "body": "Shpongle's first live performance occurred at the Solstice Music Festival in Japan in July 2001. They have toured extensively, including a sold-out concert at The Roundhouse in London in 2008 and performances at Red Rocks Amphitheater in 2014 and 2019. In 2011, they introduced the \"Shpongletron,\" a visual setup designed by artist Zebbler featuring a DJ booth and video-mapped projection surfaces. They announced their last full public concerts in September 2018 for May 2019 at Red Rocks."}], "facts": [{"label": "Formed", "value": "1996"}, {"label": "Members", "value": "Simon Posford and Raja Ram"}, {"label": "Genre", "value": "Psybient, psychedelic electronic music"}, {"label": "Debut Album", "value": "Are You Shpongled? (1998)"}, {"label": "First Live Performance", "value": "Solstice Music Festival, Japan (July 2001)"}, {"label": "Last Full Public Concerts", "value": "Red Rocks Amphitheater (May 3-4, 2019)"}], "secs": 31.5}, "gemma-small": {"lede": "Shpongle is a psychedelic electronic music project from England that formed in 1996. The group includes Simon Posford and Raja Ram, who are considered progenitors of the psybient genre. Their musical style combines traditional world music with contemporary western synthesizer-based psychedelic music.", "sections": [{"heading": "", "body": "Shpongle's sound is characterized by a combination of traditional music from around the world, vocals, and modern Western synthesizer-based psychedelic music. Posford has described their music as 'like nothing you've ever heard before.' The project is heavily influenced by psychedelic experiences, frequently utilizing sonic textures that approximate altered states of awareness. Raja Ram stated that \"Shpongle\" itself is an umbrella term for feeling positive and euphoric emotions."}, {"heading": "", "body": "The duo released their first track, \"Vapour Rumours,\" on TIP Records' Infinite Excursions compilation in 1996. Their debut album, Are You Shpongled?, followed in 1998 on Twisted Records. Subsequent albums include Tales of the Inexpressible (2001), Nothing Lasts... But Nothing Is Lost (2005), and Museum of Consciousness (2013). More recently, they released Codex VI in 2017, and as of 2024, Simon Posford and Raja Ram have released Improvisations for Piano & Flute. The group has also been releasing remasters and special edition vinyl records since June 2017."}, {"heading": "", "body": "Shpongle's first live performance was at the Solstice Music Festival in Japan in July 2001. Simon Posford frequently tours, performing DJ sets, while Raja Ram occasionally accompanies these with live flute performances. Notable live shows include a concert at The Roundhouse venue in North London on October 31, 2008, and a full ensemble performance at Camp Bisco X in New York on July 8, 2011. In May 2014, they performed with a full 12-piece band at Red Rocks Amphitheater."}, {"heading": "", "body": "Simon Posford is generally responsible for the synthesizers, studio work, and live instrumentation. Raja Ram contributes broad musical concepts and flute arrangements. For their live performances, Shpongle has utilized various supporting musicians, including Andy Gangadeen (drums), Nogera (percussion), Chris Taylor (bass), Pete Callard (guitar), Harry Escott (cello), and Dick Trevor (keyboards and programming)."}], "facts": [{"label": "Formation", "value": "1996"}, {"label": "Members", "value": "Simon Posford and Raja Ram"}, {"label": "Genre Progenitors", "value": "Psybient genre (combining world music with psychedelic trance and ambient)"}, {"label": "Debut Album", "value": "Are You Shpongled? (1998)"}, {"label": "First Live Performance", "value": "Solstice Music Festival, Japan (July 2001)"}, {"label": "Key Influences", "value": "Psychedelic experiences and traditional world music"}], "secs": 16.9}, "mistral": {"lede": "Shpongle is a psychedelic electronic music project from England, formed in 1996 by Simon Posford and Raja Ram. They are considered pioneers of the psybient genre, blending world music with psychedelic trance and ambient.", "sections": [{"heading": "", "body": "Shpongle was formed in 1996 by Simon Posford and Raja Ram, who is also a member of The Infinity Project. Their debut album 'Are You Shpongled?' was released in 1998 on Twisted Records. Since then, they have released six studio albums, with the latest being 'Codex VI' in 2017."}, {"heading": "", "body": "Shpongle's music combines traditional music from various cultures with contemporary synthesizer-based psychedelic music and vocals. Their style is described as 'like nothing you've ever heard before'. They often incorporate vocal samples relating to consciousness expansion, hallucinations, and altered states of awareness."}, {"heading": "", "body": "Shpongle has played several live concerts since their first performance at the Solstice Music Festival in Japan in 2001. They have toured extensively, including performances at festivals like Ozora and Rothbury, and venues such as The Roundhouse in London and Red Rocks Amphitheater in Colorado."}], "facts": [{"label": "Founding Year", "value": "1996"}, {"label": "Genres", "value": "Psybient, Psychedelic Trance, Ambient"}, {"label": "Members", "value": "Simon Posford and Raja Ram"}, {"label": "Studio Albums", "value": "Seven studio albums released"}], "secs": 18.2}, "qwen-coder": {"lede": "['Shpongle is a psychedelic electronic music project from England formed in 1996, known for blending world music with psychedelic trance and ambient sounds.', 'Their music often incorporates vocal samples related to consciousness expansion and altered states of awareness.']", "sections": [{"heading": "", "body": "Shpongle is a psychedelic electronic music project from England that formed in 1996. The group includes Simon Posford and Raja Ram, who are also part of The Infinity Project. They are considered pioneers of the psybient genre, which combines traditional world music with contemporary western synthesizer-based psychedelic music."}, {"heading": "", "body": "Shpongle's first track, 'Vapour Rumours', was released in 1996 on TIP Records' Infinite Excursions compilation. Their debut album, 'Are You Shpongled?', followed in 1998. Since then, they have released several studio albums and EPs, with their most recent being 'Improvisations for Piano & Flute' in 2024. The duo has also performed live at various festivals and venues around the world."}, {"heading": "", "body": "Shpongle's music is heavily influenced by psychedelic experiences, often incorporating vocal samples that relate to consciousness expansion, hallucinations, and altered states of awareness. Their live performances have featured a full ensemble with additional musicians such as Joe Russo on drums and other collaborators."}], "facts": [{"label": "Formation Year", "value": "1996"}, {"label": "Genre", "value": "Psybient"}, {"label": "First Album", "value": "Are You Shpongled?"}, {"label": "Latest Studio Album", "value": "Improvisations for Piano & Flute (2024)"}, {"label": "Notable Member", "value": "Simon Posford"}, {"label": "Collaborator", "value": "Raja Ram"}, {"label": "Influences", "value": "Psychedelic experiences, world music"}, {"label": "Notable Live Performance", "value": "Red Rocks Amphitheatre (2019)"}], "secs": 52.6}}}, {"subject": "lavenue", "slug": "lavenue", "lens": "encyclopedia", "models": {"gemma": {"lede": "Lavenue refers to the cookery school founded by Felix Lavenue, a pseudonym for Englishman Charles Shepperd. The institution was located at 67 Mortimer Street.", "sections": [{"heading": "", "body": "The Lavenue cookery school was established by Charles Shepperd, who used the name Felix Lavenue. Shepperd died in 1864, after which the school was run by his daughter, Agnes Mary Lavenue, who died a few months after selling the business in January 1883. In January 1883, the school was acquired by Agnes Bertha Marshall and her husband Alfred William Marshall. Following the purchase, the Marshalls renamed the institution as the Marshall's School of Cookery."}, {"heading": "", "body": "Shortly after the acquisition in 1883, the school was moved from its original location at 67 Mortimer Street to 30 Mortimer St because the building at 67 Mortimer Street was scheduled for demolition."}], "facts": [{"label": "Founder", "value": "Felix Lavenue (Charles Shepperd)"}, {"label": "Original Location", "value": "67 Mortimer Street"}, {"label": "Date of Acquisition by the Marshalls", "value": "January 1883"}, {"label": "label own's daughter", "value": "Agnes Mary Lavenue"}, {"label": "New Name after Acquisition", "value": "Marshall's School of Cookery"}], "secs": 42.8}, "ornith": {"lede": "Lavenue was a cookery school located at 67 Mortimer Street in Marylebone, London. It was founded by Felix Lavenue, the pseudonym of Englishman Charles Shepperd, who died in 1864.", "sections": [{"heading": "", "body": "After Felix Lavenue's death in 1864, the school was run by his daughter, Agnes Mary Lavenue. The Marylebone rate books show that 67 Mortimer Street was scheduled for demolition in 1883. A few months after selling the school, Agnes Mary Lavenue died in Tunbridge Wells."}, {"heading": "", "body": "In January 1883, Agnes and Alfred Marshall acquired the Lavenue cookery school. Although the original records of the transaction have not survived, later evidence suggests that the couple purchased the school together. This was unusual at the time, as women had only very recently earned the legal right to purchase property through the Married Women's Property Act 1882."}, {"heading": "", "body": "Soon after the purchase, the Marshalls moved the school down the road to 30 Mortimer Street and renamed it Marshall's School of Cookery. Agnes's half-brother John was employed as the school's manager, and her half-sister Ada worked for a time as the housekeeper."}], "facts": [{"label": "Founder", "value": "Felix Lavenue (pseudonym of Charles Shepperd)"}, {"label": "Location", "value": "67 Mortimer Street, Marylebone"}, {"label": "Year sold", "value": "1883"}, {"label": "Buyers", "value": "Agnes and Alfred Marshall"}, {"label": "New name", "value": "Marshall's School of Cookery"}], "secs": 21.4}, "gemma-small": {"lede": "Lavenue was the name of a cookery school that Agnes Marshall and her husband acquired in 1883. The original school, which was situated at 67 Mortimer Street, was founded by Felix Lavenue, who used this name as a pseudonym for Englishman Charles Shepperd. In 1883, the couple purchased the school from his daughter, Agnes Mary Lavenue.", "sections": [{"heading": "", "body": "The Marshall's School of Cookery, which operated at 67 Mortimer Street and later moved to 30 Mortimer St., was a major culinary institution. It taught a mixture of high-end English and French cuisine and became one of only two major cookery schools in the city, alongside The National Training School Of Cookery. Agnes Marshall's husband, Alfred, also operated other businesses through the school, including an agency that supplied domestic staff, and a food shop selling flavorings, spices, and syrups."}, {"heading": "", "body": "Agnes Bertha Marshall acquired the Lavenue cookery school in January 1883. The original founder was Felix Lavenue, who used this name as a pseudonym for Charles Shepperd, and he died in 1864. In 1883, the school was being run by his daughter, Agnes Mary Lavenue. Following the purchase, the Marshalls moved the school down the road to 30 Mortimer St. The couple purchased the school together, which was notable as women had only recently gained the legal right to purchase property through the Married Women's Property Act 1882."}, {"heading": "", "body": "Marshall published her first book, *The Book of Ices*, in 1885. This publication contained 177 different ice cream and dessert recipes and was self-published through the cookery school. The book also promoted Marshall's inventions, including the Marshall's Patent Freezer. Other innovations included an \"ice-breaking machine,\" an \"ice cave\" (an insulated box for storing ice cream), and several kitchen appliances and food ingredients."}], "facts": [{"label": "Original Founder", "value": "Felix Lavenue (pseudonym of Charles Shepperd)"}, {"label": "Acquisition Date", "value": "January 1883"}, {"label": "Initial Location", "value": "67 Mortimer Street"}, {"label": "New Location", "value": "30 Mortimer St."}], "secs": 16.5}, "mistral": {"lede": "Lavenue is a historic cookery school founded by Felix Lavenue, later acquired and renamed by Agnes Marshall, a prominent English culinary entrepreneur known for her work on ice cream.", "sections": [{"heading": "", "body": "The Lavenue cookery school was founded by Charles Shepperd under the pseudonym Felix Lavenue. Agnes Marshall and her husband Alfred acquired the school in 1883, renaming it the Marshall's School of Cookery. It taught a mixture of high-end English and French cuisine and became one of two major cookery schools in London."}, {"heading": "", "body": "Agnes Bertha Marshall (born Agnes Beere Smith) was an English culinary entrepreneur, inventor, and celebrity chef. She popularised ice cream in England and is often regarded as the inventor of the modern ice cream cone. Marshall wrote four cookbooks, including two devoted to ice cream and other desserts."}], "facts": [{"label": "Founder", "value": "Charles Shepperd (as Felix Lavenue)"}, {"label": "Acquirers", "value": "Agnes Marshall and Alfred William Marshall"}, {"label": "Year acquired", "value": "1883"}, {"label": "New name", "value": "Marshall's School of Cookery"}], "secs": 15.6}, "qwen-coder": {"lede": "['Lavenue was a cookery school in London that played a significant role in the culinary education and career of Agnes Marshall, an influential English chef.', \"Marshall renamed Lavenue to the Marshall's School of Cookery after acquiring it in 1883, transforming it into one of the leading culinary schools in London.\"]", "sections": [{"heading": "", "body": "Lavenue was originally a cookery school founded by Felix Lavenue (the pseudonym of Charles Shepperd) in 1864. It was renamed Marshall's School of Cookery after Agnes Marshall and her husband Alfred acquired it in 1883. The school became renowned for teaching high-end English and French cuisine."}, {"heading": "", "body": "The original Lavenue cookery school, located at 67 Mortimer Street, was managed by Agnes Mary Lavenue until its sale in 1883. After the purchase, the Marshalls moved the school to 30 Mortimer Street and expanded its offerings. The school's curriculum included specialized classes taught by experts from various culinary backgrounds."}, {"heading": "", "body": "Under Agnes Marshall's leadership, Marshall's School of Cookery grew rapidly in popularity and became one of the most prestigious cookery schools in London. It played a crucial role in Marshall's career development and contributed to her reputation as an influential culinary entrepreneur."}], "facts": [{"label": "Original Name", "value": "Lavenue"}, {"label": "New Name", "value": "Marshall's School of Cookery"}, {"label": "Year Acquired by Marshall", "value": "1883"}, {"label": "Location", "value": "67 Mortimer Street, then moved to 30 Mortimer Street, London"}, {"label": "Founder of Lavenue", "value": "Charles Shepperd (under the pseudonym Felix Lavenue)"}, {"label": "Number of Students", "value": "Up to 40 students per class, with nearly 2,000 students overall"}, {"label": "First Book Published by Marshall", "value": "The Book of Ices (1885)"}, {"label": "Notable Invention", "value": "Marshall's Patent Freezer"}], "secs": 50.6}}}, {"subject": "30 for 30", "slug": "30-for-30", "lens": "encyclopedia", "models": {"gemma": {"lede": "30 for 30 is a series of documentary films airing on ESPN and its sister networks, as well as online. The series highlights interesting people and events in sports history.", "sections": [{"heading": "", "body": "The series has received a mixed critical response for various episodes; for example, The A.V. Club gave positive reviews to June 17th, 1994 and Winning Time: Reggie Miller vs. the New York Knicks, while giving negative reviews to episodes involving media production arms of NASCAR, the NBA, and Major League Baseball. Ratings grew as awareness and critical acclaim increased; the first film, Kings Ransom, premiered to poor ratings with a viewership of 645,000, but by the seventh episode, The U, viewers grew to over 2 million. The series has won several awards, including a 2010 Peabody Award, a 2016 Academy Award for Best Documentary Feature for O.J.: Made in America, and Critics Choice Documentary Awards for Best Ongoing Documentary Series in 2022, 2024, and 2025."}, {"heading": "", "body": "Cadillac and Levi's are the presenting sponsors of the series. Cadillac replaced Honda as a primary sponsor. The Cadillac name appears on the logo, while the Levi's 'go forth' slogan is displayed during directors' interstitial comments at the start and end of each film. Commercials for both companies were shown during every intermission during original air dates, with Levi's guaranteed a 60-second commercial slot in the third act."}], "facts": [{"label": "Executive Producers", "value": "John Dahl, Connor Schell and Bill Simmons (as of 2010)"}, {"label": "First Film", "value": "Kings Ransom"}, {"label": "", "value": ""}], "secs": 50.5}, "ornith": {"lede": "30 for 30 is a series of documentary films airing on ESPN and its sister networks that highlights interesting people and events in sports history. The concept originated in 2007 from Bill Simmons and Connor Schell, with the title derived from the plan to produce 30 films celebrating ESPN's 30th anniversary in 2009. The series has expanded beyond its original scope to include multiple volumes, shorts, companion series like Soccer Stories, and audio podcasts.", "sections": [{"heading": "", "body": "The idea for the series began in 2007 from ESPN.com columnist Bill Simmons and ESPN's Connor Schell. The title, 30 for 30, derived from the series's genesis as 30 films in celebration of ESPN's 30th anniversary in 2009, with an exploration of the biggest stories from ESPN's first 30 years on-air, through a series of 30 one-hour films by 30 filmmakers. Volume I premiered in October 2009 and ran to December 2010, chronicling 30 stories from the \"ESPN era\", beginning with the network's founding in 1979."}, {"heading": "", "body": "The series has expanded beyond its original scope. It includes four \"volumes\" of 30 episodes each, a 13-episode series under the ESPN Films Presents title in 2011\u20132012, and a series of 30 for 30 Shorts shown through the ESPN.com website. The series has also expanded to include Soccer Stories, which aired in advance of the 2014 FIFA World Cup, and audio podcasts. In April 2018, it was announced that the entire archive of 30 for 30 films and shorts would be available on ESPN+."}, {"heading": "", "body": "The series has received significant critical acclaim and numerous awards. Notable accolades include a 2010 Peabody Award, the 2016 Academy Award for Best Documentary Feature for O.J.: Made in America, and a 2014 Primetime Emmy Award for Outstanding Short-Format Nonfiction Program. The series had a slow beginning with poor ratings for its first film but grew significantly as awareness increased."}], "facts": [{"label": "Creator", "value": "Bill Simmons and Connor Schell"}, {"label": "Premiere Date", "value": "October 2009"}, {"label": "Original Concept", "value": "30 films celebrating ESPN's 30th anniversary"}, {"label": "Notable Award", "value": "2016 Academy Award for Best Documentary Feature (O.J.: Made in America)"}, {"label": "Sponsors", "value": "Cadillac and Levi's"}], "secs": 12.7}, "gemma-small": {"lede": "30 for 30 is a series of documentary films airing on ESPN and its sister networks, highlighting significant people and events in sports history. The concept originated from Bill Simmons and Connor Schell, who conceived it as a celebration of ESPN's 30th anniversary in 2009. The series has expanded beyond the initial scope to include topics like Soccer Stories and audio podcasts.", "sections": [{"heading": "", "body": "The idea for the series began in 2007, stemming from ESPN.com columnist Bill Simmons and ESPN's Connor Schell. The title was derived from the planned release of 30 films celebrating ESPN's 30th anniversary in 2009. Volume I premiered in October 2009 and ran through December 2010, covering 30 stories from the 'ESPN era,' which began with the network's founding in 1979. Subsequent volumes and online shorts expanded the series beyond this initial timeframe."}, {"heading": "", "body": "The original format included a series of 30 one-hour films by 30 filmmakers, with Volume I detailing striking sports issues or events from the network's first three decades. The content has expanded to include Soccer Stories, which aired before the 2014 FIFA World Cup, and audio podcasts. As of April 2018, the entire archive of 30 for 30 films and shorts was announced to be available on ESPN+, ESPN's direct-to-consumer online platform."}, {"heading": "", "body": "The series has received critical recognition, including a Peabody Award Winner in 2010 and an International Documentary Association's 'Distinguished Continuing Series' that same year. Other accolades include a Primetime Emmy Award for Outstanding Short-Format Nonfiction Program (2014) and multiple Academy Awards and Peabody Awards for the film *O.J.: Made in America* (2016). The first film, *Kings Ransom*, premiered on October 6, 2009, to poor ratings, but viewership grew significantly, reaching well over 2 million viewers by the seventh episode, *The U*."}], "facts": [{"label": "Initial Concept", "value": "Began in 2007 by Bill Simmons and Connor Schell."}, {"label": "Original Purpose", "value": "To celebrate ESPN's 30th anniversary in 2009 with 30 films."}, {"label": "Volume I Timeline", "value": "Premiered October 2009 and ran to December 2010, covering the 'ESPN era'."}, {"label": "Key Sponsors", "value": "Cadillac and Levi's are presenting sponsors of the series."}], "secs": 14.8}, "mistral": {"lede": "30 for 30 is a series of documentary films airing on ESPN and its sister networks, highlighting interesting people and events in sports history. It was launched to celebrate ESPN's 30th anniversary with 30 films by 30 filmmakers.", "sections": [{"heading": "", "body": "The series began in 2009 with Volume I, which chronicled 30 stories from the 'ESPN era'. Subsequent volumes and online shorts expanded the series beyond this scope. As of now, there are four volumes, a series under ESPN Films Presents title, and various shorts."}, {"heading": "", "body": "The idea for the series was conceived by ESPN.com columnist Bill Simmons and Connor Schell in 2007. The first film, 'Peter Berg's Kings Ransom', premiered on October 6, 2009, with poor ratings but gained traction over time."}, {"heading": "", "body": "The series has received mixed reviews from critics and audiences alike. Some episodes have been praised for their storytelling and production quality, while others have been criticized for their involvement by media production arms of sports leagues."}], "facts": [{"label": "Number of films in the first volume", "value": "30"}, {"label": "Year series was launched", "value": "2009"}, {"label": "Presenting sponsors", "value": "Cadillac and Levi's"}, {"label": "Number of categories in Forbes 30 Under 30 lists", "value": "20 (for the U.S. list), 10 each for Asia and Europe, single list for Africa"}], "secs": 15.8}, "qwen-coder": {"lede": "['30 for 30 is a series of documentary films airing on ESPN and its platforms that explore interesting people and events in sports history.', \"The series began in 2009 as a celebration of ESPN's 30th anniversary, featuring 30 one-hour films by 30 filmmakers.\"]", "sections": [{"heading": "", "body": "The idea for the series originated from ESPN.com columnist Bill Simmons and ESPN's Connor Schell in 2007. The title, '30 for 30,' refers to the initial concept of creating 30 films celebrating ESPN's first 30 years on-air. Volume I premiered in October 2009 and covered significant sports stories from ESPN's founding in 1979."}, {"heading": "", "body": "The series has expanded beyond its initial volume to include additional episodes, a separate 'Soccer Stories' series, and audio podcasts. Each film delves into notable sports events or figures, with Volume I focusing on the ESPN era but subsequent volumes exploring broader sports history."}, {"heading": "", "body": "30 for 30 has received critical acclaim, with some episodes receiving prestigious awards like the Peabody Award and the Academy Award. The series' ratings grew as awareness increased, starting from poor viewership in its first episode to significant audience engagement by later installments."}], "facts": [{"label": "Series Origin", "value": "2007"}, {"label": "First Episode Title", "value": "Kings Ransom"}, {"label": "First Volume Premiere Date", "value": "October 6, 2009"}, {"label": "Number of Initial Films", "value": "30"}, {"label": "Presenting Sponsors", "value": "Cadillac and Levi's"}, {"label": "Notable Awards", "value": "2010 Peabody Award, 2016 Academy Award for Best Documentary Feature (O.J.: Made in America)"}, {"label": "Platform Availability", "value": "ESPN+, ESPN's direct-to-consumer online platform"}, {"label": "Series Expansion", "value": "Includes Soccer Stories and audio podcasts"}], "secs": 46.4}}}, {"subject": "cercle", "slug": "cercle", "lens": "collection", "models": {"gemma": {"lede": "Cercle is a French music company that produces live recordings of performances taking place in unique locations worldwide.", "sections": [{"heading": "", "body": "Recorded performances include Disclosure at Plitvice Lakes National Park, Croatia; Tame Impala at Parque de Quetzalc\u00f3atl, Mexico; ZHU at Hakuba Iwatake in Nagano, Japan; Bonobo Solo live at Cercle Odyssey in Paris, France; Shimza at Citadelle de Sisteron, France; and ARTBAT at Bondinho P\u00e3o de A\u00e7\u00facar in Rio de Janeiro, Brazil."}, {"heading": "", "body": "Performances are available as video recordings on YouTube via the Cercle channel."}, {"heading": "", "body": "Cercle's programming features electronic music artists such as Disclosure, Tame Impala, ZHU, Bonobo, Shimza, and ARTBAT performing in scenic or historic locations including national parks, citadels, and landmarks like Bondinho P\u00e3o de A\u00e7 uma sugarloaf mountain cable car."}], "facts": [{"label": "Founded", "value": "Not specified"}, {"label": "Location", "value": "France"}, {"label": "", "value": ""}, {"label": "Notable Artists", "value": "Disclosure, Tame Impala, ZHU, Bonobo, Shimza, ARTBAT"}, {"label": "Where Recordings Live", "value": "YouTube"}], "secs": 33.2}, "ornith": {"lede": "Cercle is a French music company that produces live electronic music performances filmed in striking natural and architectural locations around the world. The project has become known for its cinematic approach to documenting DJ sets, featuring artists like Disclosure, Tame Impala, Bonobo, ZHU, Shimza, and ARTBAT performing at iconic sites such as Plitvice Lakes, Rio de Janeiro's Sugarloaf Mountain, and Paris's Cercle Odyssey venue.", "sections": [{"heading": "", "body": "Cercle has hosted performances from major electronic and experimental artists at remarkable locations. Disclosure performed at Plitvice Lakes National Park in Croatia, while Tame Impala played at Parque de Quetzalc\u00f3atl in Mexico. ZHU performed at Hakuba Iwatake in Nagano, Japan, and Shimza played at Citadelle de Sisteron in France. ARTBAT performed at Bondinho P\u00e3o de A\u00e7\u00facar (Sugarloaf Mountain) in Rio de Janeiro, Brazil. Bonobo gave a solo performance at Cercle Odyssey in Paris, France."}, {"heading": "", "body": "All Cercle performances are documented as high-quality video recordings available on the Cercle YouTube channel. Each performance is typically 50-75 minutes long and features professional cinematography that emphasizes both the artist's set and the dramatic location. The videos serve as the primary archival record of these events, combining live music documentation with travel and nature content."}, {"heading": "", "body": "Cercle focuses on electronic music artists performing in visually spectacular natural landmarks and architectural sites. The project emphasizes the intersection of music, location, and visual storytelling, creating a distinctive format that differs from traditional concert documentation by prioritizing cinematic quality and unique venues over conventional stage setups."}], "facts": [{"label": "Type", "value": "French music company producing filmed live performances"}, {"label": "Format", "value": "Cinematic video recordings of DJ sets at iconic locations"}, {"label": "Notable Artists", "value": "Disclosure, Tame Impala, Bonobo, ZHU, Shimza, ARTBAT"}, {"label": "Locations Featured", "value": "Plitvice Lakes (Croatia), Rio de Janeiro (Brazil), Paris (France), Nagano (Japan), Mexico, France"}, {"label": "Video Platform", "value": "YouTube channel 'Cercle'"}], "secs": 10.2}, "gemma-small": {"lede": "This collection documents the use of 'Cercle' as a venue name or organizing label for various live music events. It is particularly valuable for documenting electronic and ambient music performances, featuring acts like Godspeed You! Black Emperor, A Silver Mt Zion, Bonobo, Tame Impala, and Disclosure. The material provides specific setlists and recordings from diverse international locations.", "sections": [{"heading": "", "body": "Godspeed You! Black Emperor performed at CAT (Cercle des Arts Traditionnels) in Bordeaux, France on January 25, 2002. A Silver Mt Zion played at Le Cercle in Qu\u00e9bec, QC, on September 24, 2010. Other notable performances include Bonobo Solo at Cercle Odyssey in Paris, France; Shimza for Cercle at Citadelle de Sisteron, France; Tame Impala at Parque de Quetzalc\u00f3atl, Mexico, for Cercle; ZHU at Hakuba Iwatake in Nagano, Japan for Cercle; ARTBAT at Bondinho P\u00e3o de A\u00e7\u00facar in Rio de Janeiro, Brazil for Cercle; and Disclosure for Cercle at Plitvice Lakes National Park, Croatia."}, {"heading": "", "body": "Recordings are available from multiple sources. Godspeed You! Black Emperor's performance in Bordeaux, France (2002) exists in two different lossless audio formats, both with excellent fidelity and stereo separation. A Silver Mt Zion's setlist from Le Cercle (2010) is documented with a running time of 102 minutes. Other performances are available as YouTube videos documenting the live event."}, {"heading": "", "body": "The material showcases diverse electronic and ambient music acts, ranging from post-rock (Godspeed You! Black Emperor) to experimental folk (A Silver Mt Zion), disco/house (Disclosure), and psychedelic pop (Tame Impala). The performances span a wide geographical range, including France, Qu\u00e9bec, Mexico, Japan, Brazil, and Croatia."}], "facts": [{"label": "Notable Artists", "value": "Godspeed You! Black Emperor, A Silver Mt Zion, Bonobo, Tame Impala, ZHU, ARTBAT, Disclosure, Shimza"}, {"label": "Locations/Venues", "value": "CAT (Cercle des Arts Traditionnels) Bordeaux, FR; Le Cercle, Qu\u00e9bec, QC; Cercle Odyssey, Paris, France; Citadelle de Sisteron, France; Parque de Quetzalc\u00f3atl, Mexico; Hakuba Iwatake in Nagano, Japan; Bondinho P\u00e3o de A\u00e7\u00facar in Rio de Janeiro, Brazil; Plitvice Lakes National Park, Croatia"}, {"label": "Performance Dates", "value": "January 25, 2002 (Godspeed You! Black Emperor); September 24, 2010 (A Silver Mt Zion)"}], "secs": 13.4}, "mistral": {"lede": "Cercle Brugge Koninklijke Sportvereniging is primarily a Belgian football club based in Bruges. However, it has also hosted notable live music performances and events under the name 'Cercle'.", "sections": [{"heading": "", "body": "Godspeed You! Black Emperor performed at Cercle des Arts Traditionnels (CAT) in Bordeaux, France on 2002-01-25. The performance was recorded and is available on Archive.org with two different lossless audio recordings. A Silver Mt Zion performed at Le Cercle in Qu\u00e9bec, Canada on 2010-09-24, also recorded and available on Archive.org."}, {"heading": "", "body": "Several performances at 'Cercle' events have been recorded and shared online. These include Disclosure at Plitvice Lakes National Park in Croatia (YouTube), Tame Impala at Parque de Quetzalc\u00f3atl in Mexico (YouTube), ZHU at Hakuba Iwatake in Nagano, Japan (YouTube), Bonobo Solo live at Cercle Odyssey in Paris, France (YouTube), Shimza at Citadelle de Sisteron in France (YouTube), and ARTBAT at Bondinho P\u00e3o de A\u00e7\u00facar in Rio de Janeiro, Brazil (YouTube)."}, {"heading": "", "body": "The 'Cercle' events seem to focus on electronic music performances in unique locations around the world. The events are recorded and shared online for viewers to enjoy."}], "facts": [{"label": "Founded", "value": "1899"}, {"label": "Location", "value": "Bruges, Belgium (football club); various locations worldwide ('Cercle' events)"}, {"label": "Format", "value": "Football club; live music performances and events in unique locations"}, {"label": "Notable Artists", "value": "Godspeed You! Black Emperor, A Silver Mt Zion (music); Disclosure, Tame Impala, ZHU, Bonobo, Shimza, ARTBAT (Cercle events)"}, {"label": "Where Recordings Live", "value": "Archive.org (Godspeed You! Black Emperor, A Silver Mt Zion); YouTube ('Cercle' events)"}], "secs": 15.4}, "qwen-coder": {"lede": "['Cercle is a label associated with various live music recordings and performances across different venues worldwide. It matters for live recordings as it curates high-quality audio and video captures of notable artists.', 'The collection includes performances by Godspeed You! Black Emperor, A Silver Mt Zion, Disclosure, Tame Impala, ZHU, Bonobo, Shimza, and ARTBAT, showcasing a diverse range of musical styles.']", "sections": [{"heading": "", "body": "Godspeed You! Black Emperor performed at CAT (Cercle des Arts Traditionnels) in Bordeaux on January 25, 2002. A Silver Mt Zion played at Le Cercle in Qu\u00e9bec on September 24, 2010. Bonobo gave a solo performance at Cercle Odyssey in Paris, France."}, {"heading": "", "body": "High-quality recordings of Godspeed You! Black Emperor's set are available on Archive.org, sourced from multiple CD-Rs and mixed for optimal audio quality. A Silver Mt Zion's performance is also archived there with detailed recording information provided."}, {"heading": "", "body": "Cercle focuses on capturing live performances of diverse artists in various locations around the world, including France, Croatia, Mexico, Japan, and Brazil. The label emphasizes high-fidelity recordings and showcases a mix of electronic, indie, and experimental music."}], "facts": [{"label": "Notable Artists", "value": "Godspeed You! Black Emperor, A Silver Mt Zion, Disclosure, Tame Impala, ZHU, Bonobo, Shimza, ARTBAT"}, {"label": "Where Recordings Live", "value": "Archive.org and YouTube"}, {"label": "Format", "value": "Audio recordings (FLAC), video performances (YouTube)"}, {"label": "Locations of Performances", "value": "CAT, Bordeaux; Le Cercle, Qu\u00e9bec; Parque de Quetzalc\u00f3atl, Mexico; Hakuba Iwatake, Japan; Cercle Odyssey, Paris; Citadelle de Sisteron, France; Bondinho P\u00e3o de A\u00e7\u00facar, Rio de Janeiro"}], "secs": 37.9}}}, {"subject": "rick rubin", "slug": "rick-rubin", "lens": "craft", "models": {"gemma": {"lede": "Rick Rubin is an American record producer and co-founder of Def Jam Recordings, founder of American Recordings, and former co-president of Columbia Records. He is known for his versatility across genres, having produced hit records for artists in hip hop, pop, heavy metal, and alternative rock.", "sections": [{"heading": "", "body": "Rubin's early production work was characterized by occasionally fusing rap with heavy rock. He is also known for creating fantastical recording environments, such as recording the Strokes' Reality Awaits in Guanacaste, Costa Rica, which resulted in a style that guitarist Albert Hammond Jr. described as \"looser\" in terms of their style."}, {"heading": "", "body": "Rubin produced Run-DMC's breakthrough act recordings and\u8005\u306f a pivotal role in the 1986 collaboration between Run-DMC and Aerosmith on a cover of \"Walk This Way,\" which is credited with introducing rap hard rock to mainstream ears. In 1986, he also produced Slayer's Reign in Blood, considered a classic of the heavy metal genre. In 1987, he produced the Cult's Electric, one of their trademark and classic works. v\u00e0 Johnny Cash's American Recordings (1994) was the first major project on his American Recordings label."}, {"heading": "", "body": "Rubin's lineage begins with his early influence from San Francisco's Flipper and friends in the NYC punk scene, including Fugazi frontman Ian MacKaye. He co-founded Def Jam Recordings with Russell Simmons after being introduced by DJ Jazzy Jay. He has worked with a wide range of artists across genres, spanning from pioneering hip hop acts like LL Cool J, Public Enemy, and the Beastie Boys\u2014whom he steered away from punk toward rap\u2014to heavy metal bands like Metallica and Slayer, and country artists such as Johnny Cash."}, {"heading": "", "body": "Rubin has been described by MTV in 2007 as \"the most important producer of the last 20 years\" and was named on Time's 2007 list of the \"100 Most Influential People in the World\". He was inducted into the Rock and Roll Hall of Fame in 2026."}], "facts": [{"label": "Era", "value": "1980s to present"}, {"label": "Genres", "value": "Hip hop, pop, pop, heavy metal, alternative rock, hard rock, nu metal, and country"}, {"label": "Notable Productions", "value": "Slayer's Reign in Blood, Run-DMC and Aerosmith's \"Walk This Way\", the Cult's Electric, Johnny Cash's American Recordings"}, {"label": "CRAFT AND CANON", "value": ""}, {"label": "Labels", "value": "Def Jam Recordings, American Recordings, Columbia Records"}, {"label": "label", "value": "Fusing rap with heavy rock; utilizing unique recording environments (e.g., Costa Rica)"}], "secs": 64.3}, "ornith": {"lede": "Rick Rubin is an American record producer and co-founder of Def Jam Recordings who helped popularize hip hop in the 1980s before building a decades-spanning career across rock, metal, country, and pop. He is known for his minimalist production approach and ability to work with artists from vastly different genres, earning him recognition as one of the most influential producers of his era.", "sections": [{"heading": "", "body": "Rubin's productions are characterized by occasionally fusing rap with heavy rock. He is known for a minimalist approach that emphasizes performance and atmosphere over technical polish, often working in unconventional environments such as recording The Strokes in Costa Rica. His method focuses on creating an environment where artists feel free to explore, described by collaborators as having 'no hidden agenda or secret.'"}, {"heading": "", "body": "Key productions include LL Cool J's 'I Need a Beat' (1984), which was Def Jam's first release; Run-DMC and Aerosmith's collaboration on 'Walk This Way' (1986), credited with introducing rap hard rock to mainstream ears; Slayer's Reign in Blood (1986), considered a classic of heavy metal; The Cult's Electric (1987); Johnny Cash's American Recordings (1994); and The Strokes' Reality Awaits (2026). He also won Album of the Year Grammys with The Chicks in 2007 and Adele in 2012."}, {"heading": "", "body": "Rubin co-founded Def Jam with Russell Simmons after being introduced by DJ Jazzy Jay. He worked closely with LL Cool J, the Beastie Boys, Run-DMC, Public Enemy, and Geto Boys in establishing hip hop's mainstream presence. His rock collaborations include Slayer, The Cult, Danzig, Metallica, Red Hot Chili Peppers, Rage Against the Machine, Johnny Cash, and The Strokes. He also produced for pop artists including Kesha, Adele, Ed Sheeran, Lady Gaga, and country acts like The Avett Brothers and Kid Rock."}, {"heading": "", "body": "In 2007, MTV called Rubin 'the most important producer of the last 20 years,' and he was named to Time's list of the '100 Most Influential People in the World.' He holds eight Grammy Awards and was inducted into the Rock and Roll Hall of Fame in 2026. His work helped define multiple genres, from hip hop to heavy metal to country, making him one of the most versatile and influential producers in music history."}], "facts": [{"label": "Born", "value": "March 10, 1963"}, {"label": "Co-founded", "value": "Def Jam Recordings (1984)"}, {"label": "Founded", "value": "American Recordings (originally Def American Recordings, renamed 1993)"}, {"label": "Grammy Awards", "value": "Eight total, including Album of the Year with The Chicks (2007) and Adele (2012)"}, {"label": "Hall of Fame", "value": "Rock and Roll Hall of Fame inductee (2026)"}, {"label": "Key Hip Hop Acts", "value": "LL Cool J, Beastie Boys, Run-DMC, Public Enemy, Geto Boys"}, {"label": "Rock/Metal Acts", "value": "Slayer, The Cult, Danzig, Metallica, Red Hot Chili Peppers, Rage Against the Machine"}, {"label": "Recognition", "value": "Called 'the most important producer of the last 20 years' by MTV (2007)"}], "secs": 29.5}, "gemma-small": {"lede": "Rick Rubin is an American record producer known for his broad influence across multiple genres, including hip hop, heavy metal, and alternative rock. His signature approach involves guiding artists to achieve a raw, powerful sound while maintaining creative integrity. He has been credited with producing seminal works that helped define the sounds of various musical eras.", "sections": [{"heading": "", "body": "Rubin's work spans an incredibly diverse range of genres, from pop and country to heavy metal and hip hop. His productions are characterized by helping artists achieve a powerful sound while maintaining creative depth. He was instrumental in pointing the Beastie Boys away from their punk roots and into rap, and his collaborations often resulted in fusing different styles, such as combining rap with heavy rock (e.g., Run-DMC and Aerosmith's 'Walk This Way')."}, {"heading": "", "body": "Key landmark productions include producing Slayer\u2019s *Reign in Blood*, considered a classic of the heavy metal genre, and his work with The Cult on their pivotal third album, *Electric*. He was also involved in the breakthrough success of Run-DMC's 1985 EP, which featured production work that helped launch the group's mainstream hip hop career. More recently, he produced The Strokes\u2019 *Reality Awaits* (2026), an album recorded partly in Guanacaste, Costa Rica."}, {"heading": "", "body": "Rubin co-founded Def Jam Recordings and later American Recordings. His early career saw him working with seminal hardcore bands like Minor Threat and playing with the band Hose. He established a long musical partnership with Slayer, producing *Reign in Blood*. In the hip hop sphere, he worked extensively with Public Enemy, LL Cool J, and Run-DMC. Later, his work included pop acts such as Adele and Lady Gaga, and country artists like Johnny Cash."}, {"heading": "", "body": "Rubin's canonical status is defined by his ability to successfully bridge disparate genres\u2014from punk roots to mainstream hip hop, from hard rock to country. He was called 'the most important producer of the last 20 years' by MTV in 2007 and has been recognized for his profound influence on music across multiple decades."}], "facts": [{"label": "Co-Founding Roles", "value": "Def Jam Recordings, American Recordings"}, {"label": "Genre Range", "value": "Hip hop, pop (Adele, Lady Gaga), heavy metal (Slayer), alternative rock (The Strokes, The Cult), country (Johnny Cash)"}, {"label": "Signature Method/Gear", "value": "Guiding artists to achieve a raw, powerful sound while maintaining creative integrity."}, {"label": "Notable Productions", "value": "Run-DMC's breakthrough EP; Slayer\u2019s *Reign in Blood*; The Strokes' *Reality Awaits* (2026)"}, {"label": "Career Milestones", "value": "Inducted into the Rock and Roll Hall of Fame in 2026."}], "secs": 14.5}, "mistral": {"lede": "Rick Rubin is an American record producer known for his signature raw and organic sound across various genres. He co-founded Def Jam Recordings and has produced landmark records like 'Licensed to Ill' by the Beastie Boys and 'American' by Johnny Cash.", "sections": [{"heading": "", "body": "Rubin is renowned for his minimalistic approach, stripping away unnecessary elements to focus on raw emotion and organic sound. He often uses analog equipment and emphasizes live recording techniques. His productions are characterized by heavy bass, prominent drums, and clear vocals, allowing artists' personalities to shine through."}, {"heading": "", "body": "Rubin's discography includes numerous influential albums:\n- 'Licensed to Ill' (Beastie Boys, 1986): Helped popularize hip hop by blending it with rock.\n- 'Reign in Blood' (Slayer, 1986): A classic heavy metal album that showcased Rubin's ability to capture raw intensity.\n- 'American' (Johnny Cash, 1994): Revitalized Cash's career with stripped-down, emotional performances.\n- 'The Blue Album' (Weezer, 1994): Helped define the alternative rock sound of the '90s.\n- 'To Bring You My Love' (PJ Harvey, 1995): Demonstrated Rubin's ability to work with singer-songwriters."}, {"heading": "", "body": "Rubin has collaborated extensively with artists like the Beastie Boys, LL Cool J, Public Enemy, Metallica, Tom Petty, and Red Hot Chili Peppers. His influence can be seen in producers like Dr. Dre, Scott Weiland, and Butch Vig."}, {"heading": "", "body": "Rubin's impact on music is undeniable. He was named one of Time's '100 Most Influential People' in 2007 and inducted into the Rock & Roll Hall of Fame in 2026. His ability to work across genres, from hip hop to country, has made him a legendary figure in music production."}], "facts": [{"label": "Era", "value": "Active since the early 1980s"}, {"label": "Genres", "value": "Hip hop, rock, metal, alternative, country, pop"}, {"label": "Notable Productions", "value": "Over 250 albums, including 'Licensed to Ill', 'American', 'The Blue Album'"}, {"label": "Labels", "value": "Def Jam Recordings, Def American/American Recordings"}, {"label": "Signature Method/Gear", "value": "Analog equipment, live recording techniques, minimalistic approach"}], "secs": 22.6}, "qwen-coder": {"lede": "['Rick Rubin is an influential American record producer known for his work across various genres including hip hop, heavy metal, alternative rock, and country music.', 'His signature as a producer is characterized by a raw, stripped-down sound that emphasizes the authenticity of the artist.']", "sections": [{"heading": "", "body": "Rubin's production style is marked by its minimalism and focus on capturing the essence of an artist. He often uses unconventional recording techniques, such as recording in natural settings or using vintage equipment to achieve a unique sound. His work with artists like Johnny Cash exemplifies his ability to bring out raw emotion and authenticity."}, {"heading": "", "body": "LL Cool J's 'I Need a Beat' (1984) was Def Jam Recordings' first release, setting the stage for Rubin's impact on hip hop. The Beastie Boys' '(You Gotta) Fight for Your Right (To Party!)' (1986), featuring a collaboration with Aerosmith, introduced rap hard rock to mainstream audiences. Johnny Cash's 'American Recordings' (1994) showcased Rubin's ability to work with artists from different eras and genres, blending traditional country music with contemporary sounds."}, {"heading": "", "body": "Rubin has collaborated with a diverse array of artists including LL Cool J, the Beastie Boys, Run-DMC, Public Enemy, Johnny Cash, The Chicks, and The Strokes. His partnership with Russell Simmons at Def Jam Recordings was pivotal in popularizing hip hop, while his work with Slayer and Metallica established him as a significant figure in heavy metal production."}, {"heading": "", "body": "Rubin's influence extends beyond individual records to the broader landscape of music production. His ability to produce hits across multiple genres and eras, coupled with his innovative techniques, has made him one of the most important producers of the last few decades. Inducted into the Rock and Roll Hall of Fame in 2026, Rubin's legacy is cemented by his contributions to shaping modern music."}], "facts": [{"label": "Era", "value": "1980s-present"}, {"label": "Genres", "value": "Hip hop, heavy metal, alternative rock, country"}, {"label": "Notable Productions", "value": "LL Cool J's 'I Need a Beat', The Beastie Boys' '(You Gotta) Fight for Your Right (To Party!)', Johnny Cash's 'American Recordings'"}, {"label": "Labels", "value": "Def Jam Recordings, American Recordings"}, {"label": "Signature Method/Gear", "value": "Minimalist production style, use of vintage equipment, recording in natural settings"}], "secs": 56.2}}}]};
const COLORS={gemma:'#7cc4ff',ornith:'#ff8a8a','gemma-small':'#9ad0a0',mistral:'#d0a0ff','qwen-coder':'#ffd27c'};
const present=D.order.filter(m=>D.subjects.some(s=>s.models[m]));
let active=present.includes('gemma')?'gemma':present[0];
function esc(s){return (s==null?'':(''+s)).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function tabs(){document.getElementById('tabs').innerHTML=present.map(m=>
  `<span class="tab${m===active?' on':''}" style="${m===active?`background:${COLORS[m]||'#888'};border-color:${COLORS[m]||'#888'}`:''}" onclick="setActive('${m}')">${m}</span>`).join('');}
function render(){tabs();
  document.getElementById('list').innerHTML=D.subjects.map(s=>{
    const m=s.models[active];
    const others=D.order.filter(o=>o!==active&&s.models[o]).map(o=>`<a onclick="jump('${s.slug}','${o}')">${o}</a>`).join(' · ')||'—';
    if(!m) return `<div class=card id="s-${s.slug}"><div class=head><span class=title>${esc(s.subject)}</span><span class=lens>${esc(s.lens)}</span></div><div class=miss>${esc(active)} has no result for this subject</div><div class=others>other models: ${others}</div></div>`;
    const full=(m.sections||[]).map(x=>`<h4>${esc(x.heading)}</h4><p>${esc(x.body)}</p>`).join('')
      +'<div class=facts>'+(m.facts||[]).map(f=>`<span class=fact><b>${esc(f.label)}</b> ${esc(f.value)}</span>`).join('')+'</div>';
    return `<div class=card id="s-${s.slug}">
      <div class=head onclick="this.parentNode.classList.toggle('open')"><span class=title>${esc(s.subject)}</span><span class=lens>${esc(s.lens)}</span><span class=arrow>▸</span></div>
      <p class=lede>${esc(m.lede)}</p><div class=full>${full}</div>
      <div class=others>other models: ${others}</div></div>`;
  }).join('');}
function setActive(m){active=m;render();}
function jump(slug,model){setActive(model);const el=document.getElementById('s-'+slug);if(el){el.classList.add('open');el.scrollIntoView({behavior:'smooth',block:'center'});}}
render();
</script>
